    h,w=len(g),len(g[0])
    start=next((r,c) for r in range(h) for c in range(w) if g[r][c]==3)
    lines=[]
    for r in range(h):
        cells=[c for c in range(w) if g[r][c] in (1,2)]
        if cells:
            lines.append((r,min(cells),max(cells)))
            for c in cells:
                g[r][c]=2
    x=start[1]
    previous_y=0
    turns=[2]+[(lines[i][0]+lines[i+1][0])//2 for i in range(len(lines)-1)]
    for y,(line_y,left,right) in zip(turns,lines):
        for r in range(previous_y,y+1):
            g[r][x]=3
        distance=line_y-y
        if left==0:
            next_x=right+distance
        else:
            next_x=left-distance
        for c in range(min(x,next_x),max(x,next_x)+1):
            g[y][c]=3
        x=next_x
        previous_y=y
    for r in range(previous_y,h):
        g[r][x]=3
    return g
